class Solution { fun minAbsoluteSumDiff(nums1:IntArray,nums2:IntArray):Int{val sorted=nums1.sorted();var total=0L;var bestGain=0;for(i in nums1.indices){val original=kotlin.math.abs(nums1[i]-nums2[i]);total+=original;var index=sorted.binarySearch(nums2[i]);if(index<0)index=-index-1;var closest=Int.MAX_VALUE;if(index<sorted.size)closest=minOf(closest,kotlin.math.abs(sorted[index]-nums2[i]));if(index>0)closest=minOf(closest,kotlin.math.abs(sorted[index-1]-nums2[i]));bestGain=maxOf(bestGain,original-closest)};return ((total-bestGain)%1_000_000_007).toInt()} }
